typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)/2;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*n){HE top=h[0];HE last=h[--(*n)];int i=0,m=*n;while(1){int c=2*i+1;if(c>=m)break;if(c+1<m&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(m>0)h[i]=last;return top;}

/* sparse SSP. rowptr/colidx CSR. returns 0 ok, -1 infeasible */
static int ssp(int n,const double*M,const int*rp,const int*ci,int*rowm,int*colm,double*v,double*u){
  double*d=malloc(n*sizeof(double));char*done=calloc(n,1);int*pred=malloc(n*sizeof(int));
  int*touched=malloc(n*sizeof(int));int*scanned=malloc(n*sizeof(int));
  int hcap=rp[n]+n+16;HE*h=malloc(hcap*sizeof(HE));
  for(int j=0;j<n;j++){d[j]=INFINITY;colm[j]=-1;v[j]=INFINITY;}
  for(int i=0;i<n;i++){rowm[i]=-1;for(int e=rp[i];e<rp[i+1];e++){int j=ci[e];double c=M[(long)i*n+j];if(c<v[j])v[j]=c;}}
  for(int j=0;j<n;j++)if(!isfinite(v[j])){return -1;}
  /* greedy init: tight edges */
  for(int i=0;i<n;i++){for(int e=rp[i];e<rp[i+1];e++){int j=ci[e];if(colm[j]<0&&M[(long)i*n+j]-v[j]==0.0){colm[j]=i;rowm[i]=j;break;}}}
  int ret=0;
  for(int s=0;s<n;s++){if(rowm[s]>=0)continue;
    int nt=0,ns=0,hn=0;
    for(int e=rp[s];e<rp[s+1];e++){int j=ci[e];double r=M[(long)s*n+j]-v[j];if(r<d[j]){if(d[j]==INFINITY)touched[nt++]=j;d[j]=r;pred[j]=s;hpush(h,&hn,r,j);}}
    int sink=-1;double delta=0;
    while(hn>0){HE t=hpop(h,&hn);int j=t.j;if(done[j]||t.d>d[j])continue;done[j]=1;scanned[ns++]=j;
      if(colm[j]<0){sink=j;delta=t.d;break;}
      int r=colm[j];double ur=M[(long)r*n+j]-v[j];
      for(int e=rp[r];e<rp[r+1];e++){int k=ci[e];if(done[k])continue;double nd=t.d+M[(long)r*n+k]-ur-v[k];
        if(nd<d[k]){if(d[k]==INFINITY)touched[nt++]=k;d[k]=nd;pred[k]=r;if(hn>=hcap){hcap*=2;h=realloc(h,hcap*sizeof(HE));}hpush(h,&hn,nd,k);}}
    }
    if(sink<0){ret=-1;break;}
    for(int q=0;q<ns;q++){int j=scanned[q];v[j]+=d[j]-delta;}
    int j=sink;while(1){int r=pred[j];int pj=rowm[r];colm[j]=r;rowm[r]=j;if(r==s)break;j=pj;}
    for(int q=0;q<nt;q++){int j2=touched[q];d[j2]=INFINITY;done[j2]=0;}
  }
  if(ret==0)for(int i=0;i<n;i++)u[i]=M[(long)i*n+rowm[i]]-v[rowm[i]];
  free(d);free(done);free(pred);free(touched);free(scanned);free(h);return ret;
}

/* returns 0 if optimal found, else -1 */
int solve(int n,const double*M,int k,int*rowm){
  if(k>n)k=n;
  int cap=2*n*k+16;int*ei=malloc(cap*sizeof(int)),*ej=malloc(cap*sizeof(int));int ne=0;
  double*bd=malloc(k*sizeof(double));int*bj=malloc(k*sizeof(int));
  for(int i=0;i<n;i++){int c=0;const double*row=M+(long)i*n;
    for(int j=0;j<n;j++){double x=row[j];if(c<k){int p=c++;while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;}bd[p]=x;bj[p]=j;}
      else if(x<bd[k-1]){int p=k-1;while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;}bd[p]=x;bj[p]=j;}}
    for(int q=0;q<c;q++){ei[ne]=i;ej[ne]=bj[q];ne++;}}
  /* column kth-smallest threshold */
  double*cd=malloc((long)n*k*sizeof(double));int*cc=calloc(n,sizeof(int));int*cr=malloc((long)n*k*sizeof(int));
  for(int i=0;i<n;i++){const double*row=M+(long)i*n;for(int j=0;j<n;j++){double x=row[j];double*D=cd+(long)j*k;int*R=cr+(long)j*k;int c=cc[j];
    if(c<k){int p=c;cc[j]++;while(p>0&&D[p-1]>x){D[p]=D[p-1];R[p]=R[p-1];p--;}D[p]=x;R[p]=i;}
    else if(x<D[k-1]){int p=k-1;while(p>0&&D[p-1]>x){D[p]=D[p-1];R[p]=R[p-1];p--;}D[p]=x;R[p]=i;}}}
  for(int j=0;j<n;j++)for(int q=0;q<cc[j];q++){ei[ne]=cr[(long)j*k+q];ej[ne]=j;ne++;}
  free(cd);free(cc);free(cr);free(bd);free(bj);
  int*colm=malloc(n*sizeof(int));double*v=malloc(n*sizeof(double)),*u=malloc(n*sizeof(double));
  int*rp=malloc((n+1)*sizeof(int));int*ci=NULL;int ret=-1;
  for(int iter=0;iter<20;iter++){
    memset(rp,0,(n+1)*sizeof(int));for(int e=0;e<ne;e++)rp[ei[e]+1]++;for(int i=0;i<n;i++)rp[i+1]+=rp[i];
    ci=realloc(ci,(ne+1)*sizeof(int));int*pos=malloc(n*sizeof(int));memcpy(pos,rp,n*sizeof(int));
    for(int e=0;e<ne;e++)ci[pos[ei[e]]++]=ej[e];free(pos);
    if(ssp(n,M,rp,ci,rowm,colm,v,u)!=0){ret=-1;break;}
    int added=0;
    for(int i=0;i<n;i++){const double*row=M+(long)i*n;double ui=u[i];for(int j=0;j<n;j++){if(row[j]-ui-v[j]<-1e-12){
      if(ne>=cap){cap*=2;ei=realloc(ei,cap*sizeof(int));ej=realloc(ej,cap*sizeof(int));}ei[ne]=i;ej[ne]=j;ne++;added++;}}}
    if(!added){ret=0;break;}
  }
  free(ei);free(ej);free(colm);free(v);free(u);free(rp);free(ci);return ret;
}
