  int T=NTH<1?1:(NTH>MAXT?MAXT:NTH);if(n<64)T=1;
  pthread_t th[MAXT];targ ta[MAXT];
  for(int t=0;t<T;t++){ta[t].f=f;ta[t].tid=t;ta[t].lo=(long)n*t/T;ta[t].hi=(long)n*(t+1)/T;ta[t].arg=arg;}
  for(int t=1;t<T;t++)pthread_create(&th[t],NULL,trun,&ta[t]);
  trun(&ta[0]);
  for(int t=1;t<T;t++)pthread_join(th[t],NULL);
}

static double qsel(double*a,int n,int k){int l=0,r=n-1;while(l<r){double p=a[(l+r)>>1];int i=l,j=r;while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}return a[k];}

/* shared state for jobs */
static double THR;static int KK;
static double*cminT[MAXT];static int*ccT[MAXT];static int*tmpT[MAXT];static double*tcT[MAXT];
static const double*PP;static const int*ORD;static double*UU;static const double*VV;static const int*TOUCH;static int NTOUCH;
static long ADDT[MAXT];

static void job_build(int tid,int lo,int hi,void*arg){
  int n=n_;const double*M=MM;double*cm=cminT[tid];int*cc=ccT[tid];int*tmp=tmpT[tid];double*tc=tcT[tid];
  for(int j=0;j<n;j++){cm[j]=INFINITY;cc[j]=0;}
  __m256d T=_mm256_set1_pd(THR);
  for(int i=lo;i<hi;i++){const double*row=M+(long)i*n;int c=0;int j=0;
    for(;j+4<=n;j+=4){__m256d x=_mm256_loadu_pd(row+j);_mm256_storeu_pd(cm+j,_mm256_min_pd(x,_mm256_loadu_pd(cm+j)));int m=_mm256_movemask_pd(_mm256_cmp_pd(x,T,_CMP_LT_OQ));
      while(m){int b=__builtin_ctz(m);m&=m-1;tmp[c]=j+b;tc[c]=row[j+b];c++;}}
    for(;j<n;j++){cm[j]=row[j]<cm[j]?row[j]:cm[j];if(row[j]<THR){tmp[c]=j;tc[c]=row[j];c++;}}
    if(c<KK){double*buf=tc+n;memcpy(buf,row,n*sizeof(double));double r=qsel(buf,n,KK-1);c=0;for(j=0;j<n;j++)if(row[j]<THR||row[j]<=r){tmp[c]=j;tc[c]=row[j];c++;}}
    for(int q=0;q<c;q++)cc[tmp[q]]++;
    adj[i]=poolI+(long)i*n;ac[i]=poolD+(long)i*n;acap[i]=n;memcpy(adj[i],tmp,c*sizeof(int));memcpy(ac[i],tc,c*sizeof(double));deg[i]=c;}
}
static int cmpbuf_dummy;
static void job_rescan(int tid,int lo,int hi,void*arg){
  int n=n_;const double*M=MM;const double*p=PP;const int*ord=ORD;int*tmp=tmpT[tid];long add=0;
  for(int i=lo;i<hi;i++){const double*row=M+(long)i*n;int*A=adj[i];double*C=ac[i];double mn=INFINITY;
    for(int e=0;e<deg[i];e++){double x=C[e]+p[A[e]];mn=x<mn?x:mn;}
    double lim=mn-THR;int c=0;
    for(int q=0;q<n;q++){int j=ord[q];if(p[j]>=lim)break;if(row[j]>=THR&&row[j]+p[j]<mn-1e-12)tmp[c++]=j;}
    for(int q=0;q<c;q++)addedge(i,tmp[q]);add+=c;}
  ADDT[tid]=add;
}
static void job_chkmin(int tid,int lo,int hi,void*arg){
  int n=n_;const double*M=MM;double*d=cminT[tid];const double*u=UU;
  for(int j=0;j<n;j++)d[j]=INFINITY;
  for(int i=lo;i<hi;i++){const double*row=M+(long)i*n;double ui=u[i];for(int j=0;j<n;j++){double x=row[j]-ui;d[j]=x<d[j]?x:d[j];}}
}
static void job_chkadd(int tid,int lo,int hi,void*arg){
  int n=n_;const double*M=MM;const double*u=UU;const double*v=VV;
  for(int i=lo;i<hi;i++){const double*row=M+(long)i*n;double ui=u[i];for(int q=0;q<NTOUCH;q++){int j=TOUCH[q];if(row[j]-ui-v[j]<-1e-13)addedge(i,j);}}
}

static void ssp(int n,int*rowm,int*colm,double*v,double*d,char*done,int*pred,int*touched,int*scanned){
  for(int s=0;s<n;s++){if(rowm[s]>=0)continue;
   while(1){
    int nt=0,ns=0,hn=0;
    {int*A=adj[s];double*C=ac[s];int dg=deg[s];
    for(int e=0;e<dg;e++){int j=A[e];double r=C[e]-v[j];if(r<d[j]){if(d[j]==INFINITY)touched[nt++]=j;d[j]=r;pred[j]=s;hpush(&hn,r,j);}}}
    int sink=-1;double delta=0;
    while(hn>0){HE t=hpop(&hn);int j=t.j;if(done[j]||t.d>d[j])continue;done[j]=1;scanned[ns++]=j;
      if(colm[j]<0){sink=j;delta=t.d;break;}
      int r=colm[j];double base=t.d-(MM[(long)r*n+j]-v[j]);
      int*A=adj[r];double*C=ac[r];int dg=deg[r];
      for(int e=0;e<dg;e++){int k=A[e];double nd=base+C[e]-v[k];
        if(nd<d[k]&&!done[k]){if(d[k]==INFINITY)touched[nt++]=k;d[k]=nd;pred[k]=r;hpush(&hn,nd,k);}}
    }
    if(sink>=0){
      for(int q=0;q<ns;q++){int j=scanned[q];v[j]+=d[j]-delta;}
      int j=sink;while(1){int r=pred[j];int pj=rowm[r];colm[j]=r;rowm[r]=j;if(r==s)break;j=pj;}
    }
    for(int q=0;q<nt;q++){int j2=touched[q];d[j2]=INFINITY;done[j2]=0;}
    if(sink>=0)break;
    densrow(s);
   }
  }
}

static int auction(int n,int*rowm,int*colm,double*p,double eps,int*fr,long maxbids,int first){
  int nf=0;
  if(first){for(int i=0;i<n;i++)rowm[i]=-1;for(int j=0;j<n;j++)colm[j]=-1;for(int i=0;i<n;i++)fr[nf++]=i;}
  else{for(int i=0;i<n;i++){int j=rowm[i];if(j<0){fr[nf++]=i;continue;}double mn=INFINITY;int*A=adj[i];double*C=ac[i];for(int e=0;e<deg[i];e++){double x=C[e]+p[A[e]];mn=x<mn?x:mn;}
      if(MM[(long)i*n+j]+p[j]>mn+eps){rowm[i]=-1;colm[j]=-1;fr[nf++]=i;}}}
  long bids=0;
  while(nf>0){int i=fr[--nf];if(++bids>maxbids){fr[nf++]=i;return nf;}
    int*A=adj[i];double*C=ac[i];int dg=deg[i];
    double w1=INFINITY,w2=INFINITY;int j1=-1;
    for(int e=0;e<dg;e++){double x=C[e]+p[A[e]];int lt=x<w1;double mx=x>w1?x:w1;w2=mx<w2?mx:w2;j1=lt?A[e]:j1;w1=lt?x:w1;}
    if(w2==INFINITY)w2=w1+1.0;
    p[j1]+=w2-w1+eps;
    int o=colm[j1];colm[j1]=i;rowm[i]=j1;if(o>=0){rowm[o]=-1;fr[nf++]=o;}
  }
  return 0;
}

static const double*vs;
static int cmpva(const void*a,const void*b){double x=vs[*(const int*)a],y=vs[*(const int*)b];return x<y?-1:(x>y?1:0);}

int KMIN=12,AREP=3,AMIN=50;double EPS0=0.02,EPSF=2e-3,EPSFAC=10;

/* returns >=0 on success */
int solve(int n,const double*M,double thr,int*rowm){
  n_=n;MM=M;THR=thr;KK=KMIN<n?KMIN:n;
  int T=NTH<1?1:(NTH>MAXT?MAXT:NTH);
  adj=malloc(n*sizeof(int*));ac=malloc(n*sizeof(double*));deg=calloc(n,sizeof(int));acap=malloc(n*sizeof(int));
  long pcap=(long)n*n+16;if(!poolI||poolcap<pcap){free(poolI);free(poolD);poolI=malloc(pcap*sizeof(int));poolD=malloc(pcap*sizeof(double));poolcap=pcap;}
  for(int t=0;t<T;t++){cminT[t]=malloc(n*sizeof(double));ccT[t]=malloc(n*sizeof(int));tmpT[t]=malloc(n*sizeof(int));tcT[t]=malloc(2*n*sizeof(double));}
  double*v=malloc(n*sizeof(double));int*tmp=malloc(n*sizeof(int));double*u=malloc(n*sizeof(double));
  double*buf=malloc(n*sizeof(double));
  pfor(n,job_build,NULL);
  int*cc=ccT[0];
  for(int j=0;j<n;j++){double m=cminT[0][j];for(int t=1;t<T;t++){cc[j]+=ccT[t][j];m=cminT[t][j]<m?cminT[t][j]:m;}v[j]=m;}
  for(int j=0;j<n;j++)if(cc[j]<KK){for(int i=0;i<n;i++)buf[i]=M[(long)i*n+j];double r=qsel(buf,n,KK-1);
    for(int i=0;i<n;i++){double x=M[(long)i*n+j];if(x<=r&&!(x<thr)){int dup=0;for(int e=0;e<deg[i];e++)if(adj[i][e]==j){dup=1;break;}if(!dup)addedge(i,j);}}}
  long tot=0;for(int i=0;i<n;i++)tot+=deg[i];
  hcap=tot+n+64;h=malloc(hcap*sizeof(HE));
  int*colm=malloc(n*sizeof(int));double*d=malloc(n*sizeof(double));char*done=calloc(n,1);
  int*pred=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int)),*scanned=malloc(n*sizeof(int));
  double*p=malloc(n*sizeof(double));for(int j=0;j<n;j++)p[j]=-v[j];
  int first=1;
  for(double eps=EPS0;;eps/=EPSFAC){if(eps<EPSF)eps=EPSF;
    int left=auction(n,rowm,colm,p,eps,tmp,200L*n,first);first=0;
    if(left||eps<=EPSF)break;}
  int*ordp=malloc(n*sizeof(int));
  for(int it=0;it<AREP;it++){
    for(int j=0;j<n;j++)ordp[j]=j;vs=p;qsort(ordp,n,sizeof(int),cmpva);
    PP=p;ORD=ordp;pfor(n,job_rescan,NULL);
    long add=0;for(int t=0;t<T;t++)add+=ADDT[t];
    if(add<AMIN)break;
    auction(n,rowm,colm,p,EPSF,tmp,200L*n,0);
  }
  /* convert to exact complementary slackness */
  for(int j=0;j<n;j++)v[j]=-p[j];
  for(int i=0;i<n;i++){int j=rowm[i];if(j<0)continue;double ui=INFINITY;for(int e=0;e<deg[i];e++){double x=ac[i][e]-v[adj[i][e]];if(x<ui)ui=x;}v[j]=M[(long)i*n+j]-ui;}
  for(int i=0;i<n;i++){int j=rowm[i];if(j<0)continue;double ui=INFINITY;for(int e=0;e<deg[i];e++){double x=ac[i][e]-v[adj[i][e]];if(x<ui)ui=x;}
    if(M[(long)i*n+j]-v[j]>ui+1e-14){rowm[i]=-1;colm[j]=-1;}}
  for(int j=0;j<n;j++){d[j]=INFINITY;}
  int ret=-1;
  for(int iter=0;iter<100;iter++){
    ssp(n,rowm,colm,v,d,done,pred,touched,scanned);
    for(int i=0;i<n;i++){int ji=rowm[i];u[i]=M[(long)i*n+ji]-v[ji];}
    UU=u;pfor(n,job_chkmin,NULL);
    for(int j=0;j<n;j++){double m=v[j];for(int t=0;t<T;t++)m=cminT[t][j]<m?cminT[t][j]:m;d[j]=m;}
    int nd=0;for(int j=0;j<n;j++)if(d[j]<v[j]-1e-13)touched[nd++]=j;
    if(!nd){ret=iter;break;}
    VV=v;TOUCH=touched;NTOUCH=nd;pfor(n,job_chkadd,NULL);
    for(int q=0;q<nd;q++){int j=touched[q];v[j]=d[j];int i=colm[j];if(i>=0){rowm[i]=-1;colm[j]=-1;}}
    for(int j=0;j<n;j++)d[j]=INFINITY;
  }
  for(int i=0;i<n;i++){if(!inpool(adj[i])){free(adj[i]);free(ac[i]);}}
  free(adj);free(ac);free(deg);free(acap);free(h);free(tmp);free(u);free(p);free(buf);free(ordp);
  for(int t=0;t<T;t++){free(cminT[t]);free(ccT[t]);free(tmpT[t]);free(tcT[t]);}
  free(colm);free(v);free(d);free(done);free(pred);free(touched);free(scanned);return ret;
}
